using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace RevitBridge.Operator
{
    internal sealed class OperatorToolInfo
    {
        public OperatorToolInfo(string group, string method, string path, string title, OperatorActionRisk risk, string description, string? example)
        {
            Group = group;
            Method = method;
            Path = path;
            Title = title;
            RiskLevel = risk;
            Risk = risk.ToString().ToLowerInvariant();
            Description = description;
            Example = example;
        }

        public string Group { get; }
        public string Method { get; }
        public string Path { get; }
        public string Title { get; }
        public string Risk { get; }

        [JsonIgnore]
        public OperatorActionRisk RiskLevel { get; }
        public string Description { get; }
        public string? Example { get; }
    }

