            new OperatorToolInfo("Computer Use", "POST", "/revit/computer-use-observe", "Observe Blocking Dialog", OperatorActionRisk.Low, "Capture the current Revit-owned blocking dialog state for GPT-5.6 computer use. Returns dialog metadata plus an optional screenshot artifact. Body: {includeScreenshot?,screenshotMaxSidePx?,maxDialogs?,onlyModal?,titleContains?,dialogIdContains?}.", "observe the current blocking dialog"),
