            new OperatorToolInfo("Spatial", "POST", "/revit/spatial-context", "Spatial Context For Room", OperatorActionRisk.Low, "Return structured room/view/coordinate context plus room contents in one native call. Body: {roomNumber, categories?, limit?}. Coordinates are Revit internal XYZ feet with Z vertical; use returned next_tools for view2D/model mapping, wall resolution, similar-device placement, adjustment, and verification.", "get spatial context for room 403 with electrical fixtures"),
