            new OperatorToolInfo("Modeling", "POST", "/revit/update-panel-parameter", "Update Panel Parameter", OperatorActionRisk.High, "Schedule-aware electrical panel updater. Finds panel schedules by exact/contains/prefix matching, resolves the backing panel element, aliases common A.I.C. wording to Short Circuit Rating, and sets the resolved panel/schedule parameter only when blank unless told otherwise. Returns sample write preflight, resolved parameter name, per-panel buckets, already-correct/skipped/failed counts, and explicit no-change alerts. Body: {scheduleQuery?|panelName?|panelNamePattern?|matchExact?,matchStartsWith?,matchContains?,exact?,max?,parameterName|requestedParameterName|parameterSemantic,value,onlyWhenBlank?,targetScope?:auto|panel|schedule,samplePanelName?,includeWritableFields?,preflightOnly?,dryRun?,apply?,confirm?}. For a single named panel, use panelName plus parameterName/value.", "set Short Circuit Rating for panel P106/7 to 10,000"),
