            new OperatorToolInfo("Spatial", "POST", "/revit/get-placement-context", "Get Placement Context", OperatorActionRisk.Low, "Return host-aware placement diagnostics for one element, including insertion point, type/family, orientation/flip state, exact serializable host-face and linked-element evidence when Revit exposes it, wall-host projection, requested room-side wall context, ranked nearby hosts, circuit membership, and read-only electrical distribution-system evidence for electrical equipment. Body: {elementId,hostCategories?,hostSearchRadiusFt?,maxNearbyHosts?,pointXyz?,roomNumber?,roomSide?}.", "get placement context for element 12345"),
            new OperatorToolInfo("Spatial", "POST", "/revit/resolve-room-wall", "Resolve Room Wall", OperatorActionRisk.Low, "Resolve the dominant room boundary wall(s) for a cardinal/view side so redline/device placement can anchor to a specific host. Body: {roomId?|roomNumber,viewId?,side,maxWalls?,includeSegments?}.", "resolve the south wall of room 403"),
            new OperatorToolInfo("Spatial", "POST", "/revit/rank-similar-devices-on-wall", "Rank Similar Devices On Wall", OperatorActionRisk.Low, "Return ranked same-room hosted device exemplars with raw XYZ, host wall, host-local chainage, orientation, room-side match, and electrical circuit audit data. Use before create-similar placement for receptacles, data outlets, nurse call, fire alarm, switches, and other hosted devices. Body: {roomId?|roomNumber?,roomSide?,referenceElementId?,targetPointXyz?|targetX/Y/Z?,targetChainageFt?|targetNormalizedChainage?,categories?,includeKeywords?,sortMode?:score_then_distance_then_coordinate|smallest_y_then_x|coordinate_x|chainage,maxCandidates?,includeRawElementPayload?}. Returns recommendedCreateSimilarRequest for /revit/create-similar-from-instance.", "rank receptacle exemplars on the left wall of room 0403 near this target point"),
            new OperatorToolInfo("Spatial", "POST", "/revit/pick-candidate-cluster", "Pick Candidate Cluster", OperatorActionRisk.Low, "Map an image-space redline point to nearby model candidates and host walls in one call. Requires an existing frameId from export-view-frame/export-visible-elements. Body: {frameId,xPx,yPx,includeCategories?,excludeCategories?,hostCategories?,roomId?|roomNumber?,roomSide?,searchRadiusFt?,maxTargets?,maxHosts?}.", "pick nearby receptacle and wall candidates at this redline point"),
