            new OperatorToolInfo("Spatial", "POST", "/revit/audit-hosted-instance-placement", "Audit Hosted Instance Placement", OperatorActionRisk.Low, "Audit created hosted instances against requested room/wall placement rules in one call. Body: {elementIds:[...],roomId?|roomNumber?,roomSide?,hostCategories?,hostSearchRadiusFt?,maxNearbyHosts?}.", "audit these created receptacles against room 403 south wall"),
            new OperatorToolInfo("Spatial", "POST", "/revit/resolve-redline-target", "Resolve Redline Target", OperatorActionRisk.Low, "Resolve candidate elements from sheet markup regions with confidence + coordinate lineage. Body: {sheetNumber,sheetRegions?,categories?,textContains?,limit?}.", "resolve the circled target on sheet A2.10"),
            new OperatorToolInfo("Spatial", "POST", "/revit/propose-fix", "Propose Spatial Fix", OperatorActionRisk.Low, "Read-only diagnostics that suggest deterministic follow-up actions for hosting/elevation mismatches. Body: {elementId,expectedHostCategory?,expectedElevationFt?,toleranceFt?}.", "propose fix for element 12345 expected on wall at 4 ft"),
            new OperatorToolInfo("Query", "POST", "/revit/find-duplicate-marks", "Find Duplicate Marks", OperatorActionRisk.Low, "Detect duplicate parameter values for a category (default air terminals mark). Body: {categoryName?,parameterName?,viewId?,includeEmpty?,maxGroups?}.", "find duplicate Mark values for air terminals"),
            new OperatorToolInfo("MEP", "POST", "/revit/airflow-qa", "Airflow QA", OperatorActionRisk.High, "HVAC/MEP QA workflows for airflow/device validation. Actions: audit_air_devices, audit_connected_flow, reconcile_air_balance_sheet, layout_air_terminals_from_sheet (one-call room-based grille placement with max CFM/device + spacing + grid-intersection/clash-avoidance heuristics), tag_airflow_terminals (one-call duct terminal tagging), apply_pressure_regions_from_sheet (green/red filled regions with transparency), and audit_medical_gas_outlets. Body: {action,dryRun?,...}.", "run airflow qa audit_air_devices with C1/C2/C3 rules"),
            new OperatorToolInfo("MEP", "POST", "/revit/mep-workflows", "MEP Workflows", OperatorActionRisk.High, "One-call HVAC workflow wrappers. Actions: set_duct_parameter_set, audit_duct_slope, create_duct_fitting_schedule, create_mechanical_plan, create_coordination_3d_view, create_sections_along_ducts, place_family_along_ducts, connect_elements_with_duct|elbow|transition|flex, route_terminals_to_equipment, place_equipment_and_connect, create_riser_offset, ensure_spaces_and_tag, create_hvac_schematic, duplicate_3d_with_section_box, create_dependent_with_crop. Body: {action,dryRun?,...}.", "run mep-workflows route_terminals_to_equipment for equipment 123"),
            new OperatorToolInfo("MEP", "POST", "/revit/resolve-mep-routing-context", "Resolve MEP Routing Context", OperatorActionRisk.Low, "Resolve deterministic MEP route context from view/room/level, including fallback elevation assumptions for incomplete redlines. Body: {viewId?,roomNumber?,levelName?,levelId?,systemKind?:duct|pipe|conduit,systemClassification?,routingMode?:auto|above_ceiling|plenum_midpoint|level_offset,defaultOffsetFt?,ceilingOffsetFt?,dryRun?}.", "resolve above-ceiling routing context for room 403"),
            new OperatorToolInfo("MEP", "POST", "/revit/create-mep-route", "Create MEP Route", OperatorActionRisk.High, "Create a multi-segment duct, pipe, or electrical conduit route from ordered XYZ or frame-linked points with dry-run, conservative size/elevation fallbacks, explicit user-workset assignment, internal connector attempts, optional fail-closed endpoint joining, and native readback. Duplicate duct/conduit type names fail closed; use ductTypeId or conduitTypeId for stable native selection. Native route size, duct shape, and requested workset readback must match when verify=true. Body: {kind:duct|pipe|conduit,frameId?,points:[{x?,y?,z?,xPx?,yPx?,xyz?}],viewId?,roomNumber?,levelName?,levelId?,worksetName?,worksetId?,systemType?,ductType?,ductTypeId?,ductShape?:round|rectangular|oval,pipeType?,conduitType?,conduitTypeId?,ductSize?,diameter?,pipeSize?,segmentSizes?:string[],sizePolicy?:explicit_required|use_default_with_warning,elevationPolicy?:explicit_required|resolve_context_default,routingMode?:orthogonal|polyline,connectSegments?,connectToExisting?,requireExistingEndpointConnections?,externalConnectionToleranceFt?,verify?,dryRun?}.", "dry-run a native conduit or duct route with three ordered points"),
            new OperatorToolInfo("MEP", "POST", "/revit/connect-mep-branch", "Connect MEP Branch", OperatorActionRisk.High, "Assess branch/tee/tap feasibility against a main duct or pipe. Apply is supported when the branch starts at an existing open main connector, when a projected non-connector branch point can split a straight main duct or pipe and create a Revit tee fitting, and for connectionMode:tap where a straight duct or pipe main receives a Revit takeoff fitting without splitting the main. For reconstruction around a retained reducer or transition, existingBranchAnchorElementId reuses exactly one compatible two-connector fitting: the main-side connector becomes the tee branch and the opposite connector receives the newly created downstream branch. Retained-anchor requests require connectionMode:tee and never fall back to an open-main or tap/takeoff path. Pipe split-tees may provide explicit branchSystemType and branchPipeType values, allowing a downstream Vent branch to join a Sanitary main without pretending the fixture has a direct vent connector; explicit overrides require connectionMode:tee and are verified after connection. Branch routes can provide branchSegmentSizes, one per branch segment, to plan/apply internal transition fittings where adjacent branch segment sizes differ. Tap requests may provide takeoffFamilyName/takeoffTypeName; apply rolls back if Revit creates a different takeoff. Body: {kind:duct|pipe,mainElementId,branchPoints:[...],branchSize?,branchSegmentSizes?:string[],branchSystemType?,branchPipeType?,connectionMode?:tee|tap|auto,existingBranchAnchorElementId?,takeoffFamilyName?,takeoffTypeName?,frameId?,viewId?,roomNumber?,levelName?,levelId?,dryRun?,verify?,visualVerify?}.", "dry-run a downstream Vent tee branch from a Sanitary pipe main"),
            new OperatorToolInfo("MEP", "POST", "/revit/connect-existing-mep-branch", "Connect Existing MEP Branch", OperatorActionRisk.High, "Create a native takeoff fitting between one exact physically open connector on an existing rigid or flex duct/pipe branch and the interior of an existing rigid main curve without creating replacement branch route elements. Dry-run performs the real Revit fitting operation inside a transaction group and rolls it back, returning the projected main point, fitting identity, physical-connectivity proof, and rollback verification. Body: {expectedModelPath?,kind:duct|pipe,mainElementId,branchElementId,branchConnectorId?,expectedBranchOriginXyz?,originToleranceFt?,expectedTakeoffTypeId?,expectedTakeoffFamilyName?,expectedTakeoffTypeName?,dryRun?,verify?}.", "dry-run attaching retained flex duct 456 connector 1 to rigid main duct 123 with an exact takeoff type"),
            new OperatorToolInfo("MEP", "POST", "/revit/connect-mep-elements", "Connect MEP Elements", OperatorActionRisk.High, "Fail-closed physical connector join for an already placed MEP family/equipment instance and explicit nearby duct, pipe, or family targets. Composes with hosted/unhosted placement, requires compatible open connector shape/domain/size within tolerance, uses one source connector per target, and rolls back if native AllRefs verification does not prove the requested count. Body: {sourceElementId,targetElementIds:[...],toleranceFt?,sizeToleranceFt?,requiredConnectionCount?,dryRun?,verify?}.", "dry-run connecting a reconstructed air terminal to its explicit open duct target"),
            new OperatorToolInfo("MEP", "POST", "/revit/create-pipe-between-connectors", "Create Pipe Between Connectors", OperatorActionRisk.High, "Fail-closed creation of one pipe between exactly one open service connector on each of two explicit elements. Resolves connector geometry natively at runtime, requires an exact service, pipe system/type/size/level and maximum length, rejects ambiguous or size-mismatched connectors, and verifies both physical owner connections with zero open connectors. Body: {sourceElementId,targetElementId,service,systemType,pipeType,pipeSize,levelName,maximumLengthFt?,sizeToleranceFt?,dryRun?,verify?}.", "dry-run a concealed lavatory cold-water stub between a placed fixture and retained anchor"),
            new OperatorToolInfo("MEP", "POST", "/revit/existing-conditions-mep-draft-workflow", "Existing Conditions MEP Draft Workflow", OperatorActionRisk.High, "Execute one source-grounded reconstruction stage. The Operator harness normally sends one dependency-ready operation per call, but may send a bounded group of explicitly marked independent high-confidence straight backbones. Each stage runs first with dryRun:true and then once with dryRun:false. Later stages pass hash-ledgered priorActionOutputs so accepted native IDs are never replayed. Each call has its own rollback boundary. Responses echo stageKey and persist created_element_ids, affected_element_ids, and route endpoint IDs; the host ledger binds planned continuation endpoints to those IDs and audits their native connectors before acceptance. In addition to route, family, connection, tag, and circuit creation, the wrapper supports repair-first move, rotate, MEP size/elevation edit, and exact connector repair operations against useful existing elements. Body: {stageKey?,priorActionOutputs?:[{action_key,created_element_ids,affected_element_ids?,route_segment_element_ids?,route_start_element_ids?,route_end_element_ids?,split_main_start_element_ids?,split_main_end_element_ids?}],operations:[{action_key,path,depends_on?,apply_body?,deferred_body?,execution_mode?,provisional_batch_key?,continuation_endpoints?}],dryRun?,verify?,maximumCreatedElements?,targetViewId?,applyTargetViewPhase?,requireAllCreatedElementsVisibleInTargetView?}.", "dry-run one repairable existing-conditions stage or bounded provisional backbone batch, apply it once, verify it, and persist created or affected IDs"),
            new OperatorToolInfo("MEP", "POST", "/revit/copy-mep-pattern", "Copy MEP Pattern", OperatorActionRisk.High, "Copy an explicit connected MEP analog as one native pattern so internal taps, hosted devices, family/type parameters, system membership, and reusable flex duct/pipe geometry can be preserved. Optional straight-curve endpoint overrides fit copied rigid curves to known anchors; copied flex curves can be reshaped afterward with /revit/repair-mep-connectors set_flex_curve. Optional externalConnections then join copied curves to explicit existing elements. External connectors must match domain, shape, and size within the requested tolerance. Dry-run executes the actual Revit copy/edit/connect operations and rolls back. Body: {sourceElementIds:[...],translationXyz:[x,y,z],curveEndpointOverrides?:[{sourceElementId,startXyz:[x,y,z],endXyz:[x,y,z]}],externalConnections?:[{copiedSourceElementId,existingElementId}],connectionToleranceFt?,connectionSizeToleranceFt?,dryRun?,verify?}.", "dry-run copying an adjacent flex-duct or rigid MEP pattern and fitting it between retained anchors"),
            new OperatorToolInfo("MEP", "POST", "/revit/mep-route-workflow", "MEP Route Workflow", OperatorActionRisk.High, "One-call duct, pipe, or native conduit route workflow that enforces resolve context -> dry-run -> optional apply -> focused post-change highlight/export. Body mirrors create-mep-route, including stable type IDs, explicit worksetName/worksetId, segmentSizes, and optional fail-closed endpoint joining, plus {apply?:boolean,visualVerify?:boolean,visualViewId?,imageSize?,focusPaddingFt?}. Visual verification is ready only when every created element is found, collected, unhidden, and has a view-specific bounding box in the requested view; otherwise it returns CreatedElementsNotVisibleInView with diagnostics.", "apply and visually verify a native conduit or duct route"),
            new OperatorToolInfo("MEP", "POST", "/revit/mep-branch-network-workflow", "MEP Branch Network Workflow", OperatorActionRisk.High, "One-call network workflow for a main duct/pipe route plus multiple branch tee/tap connections. Dry-run plans the main route, branch projections, selected sizes, retained branch anchors, branch-level reducer/transition joint plans, and accessory/damper graph nodes. Apply creates the main route first, then connects each branch to its requested main segment using /revit/connect-mep-branch; duct tap/takeoff, pipe tap/takeoff with an explicit Revit takeoff/tap routing preference, retained two-connector transition/reducer anchors, and duct/pipe split tee use the lower-level verified guards. A branch with existingBranchAnchorElementId must use connectionMode:\"tee\" and never falls back to an open-main or tap path. Accessory graph apply supports explicit duct/pipe accessory insertions hosted on created main or branch segments when a compatible loaded or workspace-scoped familyPath symbol resolves, plus explicit target-id duct/pipe accessory delete and type_change with compatible loaded types. Body: {kind:duct|pipe,mainPoints:[...],mainSegmentSizes?,branches:[{mainSegmentIndex,connectionMode?:tee|tap,connectionPoint?,points:[...],branchSize?,branchSegmentSizes?:string[],existingBranchAnchorElementId?}],accessories?:[{action:insert|delete|type_change,targetElementId?,targetElementIds?,typeId?,targetTypeName?,familySymbolId?,familyPath?,familyName?,typeName?,mainSegmentIndex?,branchIndex?,branchSegmentIndex?,chainageFt?,point?}],viewId?,roomNumber?,levelName?,systemType?,ductType?,pipeType?,ductSize?,diameter?,pipeSize?,apply?,verify?,visualVerify?}.", "dry-run main duct with two branch taps"),
            new OperatorToolInfo("MEP", "POST", "/revit/edit-mep-route-elements", "Edit MEP Route Elements", OperatorActionRisk.High, "MEP-aware explicit duct/pipe curve edit workflow. Supports dry-run/apply size changes and simple level straight elevation moves with before/after curve, size, connector, connected-network audit, and optional focused capture. Elevation moves are blocked for connected elements unless allowConnectedElevationMove:true. Body: {kind:duct|pipe,elementIds:[...],ductSize?|diameter?|pipeSize?,deltaZFt?|targetCenterlineZFt?,allowConnectedElevationMove?,apply?,dryRun?,verify?,visualVerify?,visualViewId?,focusPaddingFt?}.", "dry-run change duct ids 123,124 to 10x8 and lower them 1 ft"),
            new OperatorToolInfo("MEP", "POST", "/revit/reroute-mep-route-segment", "Reroute MEP Route Segment", OperatorActionRisk.High, "Guarded edit workflow for one straight duct/pipe curve. Offset mode derives two split points from host curve chainage or normalized chainage, reports replacement segments, offset points, selected type/system/level/size, and expected elbow fittings; offsetMode:\"dogleg45\" uses diagonal setback legs instead of perpendicular legs. Size-transition mode derives one transition point, reports upstream/downstream segment points, explicit selected sizes, and expected transition fitting. Apply replaces the host only after required fittings/connectors succeed, reports created segment/fitting ids, connector/system audit, endpointReconnectionPlan when applicable, and optional trace-enabled focused capture. Connected host endpoints are blocked by default; set preserveConnectedEndpoints:true only after dry-run reports a resolvable start/end endpointReconnectionPlan to reconnect the replacement route to original external endpoint connectors. Body offset: {kind:duct|pipe,hostElementId,split1ChainageFt?|split1Normalized?,split2ChainageFt?|split2Normalized?,offsetVector:{x,y,z},offsetMode?:orthogonal|dogleg45,doglegAngleDegrees?,preserveConnectedEndpoints?,apply?,dryRun?,verify?,visualVerify?,visualViewId?,focusPaddingFt?}. Body size-transition: {kind:duct|pipe,hostElementId,transitionChainageFt?|transitionNormalized?,upstreamDuctSize?|downstreamDuctSize?|upstreamDiameter?|downstreamDiameter?|upstreamPipeSize?|downstreamPipeSize?,sizePolicy?,preserveConnectedEndpoints?,apply?,dryRun?,verify?,visualVerify?,visualViewId?,focusPaddingFt?}.", "dry-run a 45-degree dogleg offset for isolated duct id 123"),
            new OperatorToolInfo("Modeling", "POST", "/revit/arch-workflows", "Architecture Workflows", OperatorActionRisk.High, "One-call architecture/modeling workflow wrappers. Actions: create_walls_from_polyline, change_wall_type, join_wall_geometry, place_hosted_instances, swap_family_type_in_view, create_model_group_and_place, array_elements, mirror_elements, copy_same_place, create_reference_plane, purge_duplicate_line_patterns, create_floor_from_walls, create_ceiling_in_room, create_rooms_and_tags, create_room_separation_lines. Body: {action,dryRun?,...}.", "run arch-workflows create_walls_from_polyline"),
                new OperatorToolInfo("MEP", "POST", "/revit/trace-connected-network", "Trace Connected Network", OperatorActionRisk.Low, "Trace connected MEP elements via connectors starting from an element id. Body: {startElementId, systemName?, inferSystemFromStart?, stopAtBranchFittings?, stopAtTransitions?, maxHops?, excludeElementIds?, stopAtElementIds?, stopAtCategories?, includeDucts?, includePipes?, includeFittings?, includeAccessories?, includeTerminals?, includeEquipment?, includeOtherCategories?, maxElements?, includeSystemAudit?, systemAuditMaxElements?}. Returns connected ids grouped by category and ordered by traversal; includeSystemAudit optionally reports disconnectedIds = systemElementIds - connectedIds for duct and pipe systems.", "trace the connected duct run from this element"),
            new OperatorToolInfo("MEP", "POST", "/revit/find-elements-by-parameter", "Find Elements By Parameter", OperatorActionRisk.Low, "Find elements by parameter value with optional system/view/category filters. Use legacy {parameterName|parameter|paramName,op,value} for one predicate, or {predicates:[{parameterName,op,value}],matchMode:any|all} for bounded alternatives. Body also supports {category?,categories?,systemName?,viewId?,limit?}.", "find equipment whose Mark or Name equals the supplied exact identifier"),
                new OperatorToolInfo("MEP", "POST", "/revit/room_mep_intersect", "Room MEP Intersect", OperatorActionRisk.Low, "Find duct-related elements in a room's plenum volume by geometry intersection. Body: {roomNumber, plenumTopLevelName, categories?,systemClassification?,sizeEquals?,intersectMode?:\"bbox\"|\"centerline\",verticalTolerance?,limit?}.", "find supply 8\\\" ducts in room 301 up to plenum level L4"),
                new OperatorToolInfo("MEP", "POST", "/revit/ducts-by-spatial-scope", "Ducts By Spatial Scope", OperatorActionRisk.Low, "Resolve room/space ductwork scope with fallbacks and return matching elements with size/system metadata. Body: {roomNumber,systemClassification?,sizeFrom?,verticalScope?:\"room\"|\"plenum\"|\"room+plenum\",includeCategories?:[\"Ducts\"|\"Duct Fittings\"|\"Air Terminals\"],roomMode?:\"auto\"|\"roomAware\"|\"geometry\",includeConnectedOutsideRoom?,limit?}.", "find supply ductwork in office unit 301 from 8\\\""),
                new OperatorToolInfo("MEP", "POST", "/revit/sync-connected-sizes", "Sync Connected Sizes", OperatorActionRisk.High, "Best-effort attempt to synchronize connected fitting/terminal sizes based on adjacent duct sizes (supports dry-run). Body: {startElementId?|elementIds?,mode?,dryRun?,maxElements?,confirm?}. Returns diffs + typeDriven diagnostics for elements that require type duplication + swap.", "dry-run sync connected sizes starting from this duct"),
                new OperatorToolInfo("MEP", "POST", "/revit/resize-duct-run", "Resize Duct Run", OperatorActionRisk.High, "Resize a connected round-duct run starting from an element id (duct/fitting/terminal/equipment) up to best-effort boundaries (branches/transitions/terminations). Applies duct curve diameter changes and then runs /revit/sync-connected-sizes within the traced run. Body: {startElementId,targetDiameter?|targetDiameterFt?,systemName?,inferSystemFromStart?,scope?,stopAtBranchFittings?,stopAtTransitions?,includeTerminals?,includeEquipment?,eliminateTransitions?,maxElements?,dryRun?,confirm?}.", "dry-run resize the connected duct run from this element to 6\\\""),
                new OperatorToolInfo("MEP", "POST", "/revit/resize-ducts-by-scope", "Resize Ducts By Scope", OperatorActionRisk.High, "Unified duct resize entrypoint by equipment/room/view scope. Supports room and plenum workflows with optional fitting/terminal/equipment sync and type-driven per-instance swap. Body: {scope:{type:\"equipment\"|\"room\"|\"view\",mark?|roomNumber?|plenumTopLevelName?|viewId?},systemClassification?,fromDiameter?,toDiameter,includeFittings?,includeTerminals?,includeEquipment?,scopeMode:\"connectedRun\"|\"bboxIntersect\"|\"centerlineIntersect\",roomMode?:\"geometry\"|\"roomAware\",verticalScope?:\"room\"|\"plenum\",stopAtBranchFittings?,stopAtTransitions?,resolveTypeDriven?:\"auto\"|\"duplicate\"|\"skip\",eliminateTransitions?,verify?,dryRun?,confirm?,maxElements?}.", "dry-run resize supply 8\\\" to 10\\\" by room scope"),
            new OperatorToolInfo("MEP", "POST", "/revit/resize-ducts-in-room", "Resize Ducts In Room", OperatorActionRisk.High, "Room-scoped duct resizing workflow with room/space resolution, optional plenum targeting, and type-driven handling. Body: {roomNumber,roomMode?:\"auto\"|\"geometry\"|\"roomAware\",verticalScope?:\"room\"|\"plenum\"|\"auto\"|\"room+plenum\",plenumTopLevelName?,systemClassification?,sizeFrom?,sizeTo,includeFittings?,includeTerminals?,includeEquipment?,stopAtBranchFittings?,resolveTypeDriven?:\"auto\"|\"duplicate\"|\"skip\",eliminateTransitions?,verify?,dryRun?,confirm?,maxElements?}.", "dry-run resize supply 8\\\" to 10\\\" in room 301"),
            new OperatorToolInfo("MEP", "POST", "/revit/resize-ductwork-by-scope", "Resize Ductwork By Scope", OperatorActionRisk.High, "One-shot room/space ductwork resize with built-in spatial fallback, fitting/terminal sync, continuity audit, and optional continuity repair. Body: {scope:{roomNumber,verticalScope?:\"room\"|\"plenum\"|\"room+plenum\",roomMode?:\"auto\"|\"roomAware\"|\"geometry\"},systemClassification?,sizeFrom?,sizeTo,includeFittings?,includeTerminals?,resolveTypeDriven?:\"auto\"|\"duplicate\"|\"skip\",repairContinuity?,continuityMaxGapFt?,continuityMaxRepairs?,verify?,dryRun?,confirm?,maxElements?}.", "change supply ductwork in office unit 301 from 8\\\" to 10\\\""),
            new OperatorToolInfo("MEP", "POST", "/revit/repair-duct-continuity-by-scope", "Repair Duct Continuity By Scope", OperatorActionRisk.High, "Repair continuity breaks in an exact duct element set or room/plenum scope without changing target size. The exact elementIds mode requires expectedModelPath. Supports Round, Rectangular, and Oval connector profiles; facing collinear endpoints use a direct bridge, while orthogonal endpoints use two profiled duct segments and a native elbow. Dry-run performs the native repair in one transaction, rolls it back, and verifies exact connector-topology restoration plus transient created IDs. Body: {scope?:{roomNumber,verticalScope?:\"room\"|\"plenum\"|\"room+plenum\",roomMode?:\"auto\"|\"roomAware\"|\"geometry\"},elementIds?:number[],expectedModelPath?,systemClassification?,includeTerminals?,verify?,dryRun?,maxGapFt?,maxRepairs?,maxElements?}.", "dry-run one exact rectangular orthogonal continuity repair in an authorized disposable model"),
            new OperatorToolInfo("MEP", "POST", "/revit/repair-mep-connectors", "Repair MEP Connectors", OperatorActionRisk.High, "Either (a) disconnect exact connector boundaries and leave them open for staged subgraph repair, (b) disconnect explicitly identified connector pairs, apply one bounded geometry repair, and reconnect the same connector identities in a rollback-capable transaction group, (c) native dry-run/apply one exact open-connector direct, elbow, positive-gap transition, or three-curve tee connection, optionally replacing one exact physically disconnected fitting, (d) dry-run/apply one standalone vector move, exact curve endpoint edit, exact flex duct/pipe control-point and tangent repair, or guarded round connector diameter repair, (e) dry-run/apply moving one exact connected network from a generated MEPSystem into an existing retained compatible MEPSystem, or (f) replace one or more exact generated connector-only piping systems with one new piping system from guarded connector seeds while proving geometry and physical topology are unchanged. Native connector IDs are preferred; enumeration-index identities require exact origin guards. Body: {expectedModelPath?,disconnectOnlyPairs?:[...],connectOpenPair?:{...},connectOpenTee?:{...},connectionKind?:\"auto\"|\"direct\"|\"elbow\"|\"transition\",disconnectPairs?:[...],repair?:{...},mergeMepSystem?:{sourceSystemId,targetSystemId,expectedSourceSystemName,expectedTargetSystemName,finalTargetSystemName?,expectedSourceElementIds:[...],expectedSourceNativeMemberElementIds:[...],expectedCascadeDeleteElementIds?:[...],anchorConnector:{elementId,connectorId,expectedOriginXyz?}},rebuildPipingSystem?:{expectedSystemTypeId,finalSystemName,systems:[{systemId,expectedSystemName,expectedCascadeDeleteElementIds?:[...]}],expectedElementSystemAssignments:[{elementId,systemIds:[...]}],seedConnectors:[{elementId,connectorId,expectedOriginXyz?}]},allowConnectedRepair?,maxConnectorDistanceFt?,originToleranceFt?,dryRun?,verify?}.", "dry-run rebuilding two exact split sanitary systems into one verified piping system without changing geometry or physical topology"),
            new OperatorToolInfo("MEP", "POST", "/revit/get-connectors", "Get Connectors", OperatorActionRisk.Low, "Get connector identities, origins, sizes, directions, and optional flex duct/pipe control points and tangents for MEP elements. connectorIdBasis is revit_native_connector_id when the active Revit API exposes a durable connector ID; the enumeration_index_with_origin_guard_required fallback must be paired with the returned origin in repair requests. connectedTo preserves all Revit Connector.AllRefs entries; physicalConnectedTo excludes MEPSystem membership objects so isPhysicallyConnected and physicalConnectionCount can be used for actual topology/open-connector checks. Body: {elementIds:[...], includeAllRefs?, includeCoordinateSystem?, includeFlexGeometry?, maxConnectorsPerElement?}.", "get connectors for these elements"),
            new OperatorToolInfo("Electrical", "POST", "/revit/audit-electrical-circuit-loading", "Audit Electrical Circuit Loading", OperatorActionRisk.Low, "Read-only evaluator evidence for native panel inventory or exact scoped receptacle membership, voltage, poles, breaker rating, wire-size/profile-derived conductor ampacity, and whether every native circuit member is inside the scope. It reports factual evidence only and makes no NEC/AHJ compliance claim. Body: {panelName:'PANEL-A',wireAmpacityProfiles:[...],maxElements?} or {elementIds:[...],wireAmpacityProfiles:[...],maxElements?}.", "audit a panel or selected receptacle circuits with the adopted conductor profile"),
            new OperatorToolInfo("Plumbing", "POST", "/revit/audit-plumbing-fixture-services", "Audit Plumbing Fixture Services", OperatorActionRisk.Low, "Read-only evaluator evidence for either exact fixtureElementIds or a complete level-scoped plumbing-fixture inventory, native connector classifications and sizes, direct physical connections, and graph-traced downstream continuation to an actual Revit Vent piping system. It reports facts only; fixture requirements and accepted sizes remain evaluator-owned. Body: {levelName:'L4',fixtureElementIds?:[1372407],familyMatchTokens?:['fixture connection'],typeMatchTokens?:['vanity','water closet'],maxElements?,maxVentSearchElements?,maxVentSearchHops?}. family/type tokens are required only when fixtureElementIds is empty.", "audit exact fixtures or lavatory and water-closet native plumbing services on level L4"),
            new OperatorToolInfo("MEP", "POST", "/revit/duplicate-type-and-swap-instance", "Duplicate Type + Swap Instance", OperatorActionRisk.High, "Duplicate the current type of an element instance, apply optional type parameter changes on the duplicated type, then swap only that instance to the new type. Useful for type-driven terminals/fittings. Body: {instanceId,newTypeName,typeParamChanges?,dryRun?,confirm?}.", "duplicate this terminal type to 6\\\" and swap only this instance"),
            new OperatorToolInfo("Modeling", "POST", "/revit/plan-family-evolution", "Plan Family Evolution", OperatorActionRisk.Low, "Read-only, fail-closed plan for cloning a selected loaded family, creating a type with exact width/depth, and optionally adding a light symbolic clearance rectangle. Requires immutable instance/family/type identity, fingerprints family content, and resolves side=power_connection only from one electrical connector close to an equipment edge. Body: {instanceId,expectedUniqueId,expectedMark?,expectedFamilyName,expectedTypeName,newFamilyName,newTypeName,widthParameterName?,depthParameterName?,width,depth,clearance?:{side,offset,lineStyleName?,linePatternName?,lineWeight?,red?,green?,blue?},familySavePath?}.", "plan HRU403 as 3 feet 8 inches by 4 feet 2 inches with 36 inch power-side clearance"),
            new OperatorToolInfo("Modeling", "POST", "/revit/apply-family-evolution", "Apply Family Evolution", OperatorActionRisk.High, "Apply an exact plan-family-evolution receipt. Requires the same request, planHash, and typed confirmation. Clones the family into the guarded workspace, edits the new type and symbolic clearance atomically, loads it, and swaps only the selected instance. The source family is never overwritten.", "apply the approved HRU403 family evolution plan"),
            new OperatorToolInfo("Query", "POST", "/revit/read-family-evolution", "Read Family Evolution", OperatorActionRisk.Low, "Read back the selected instance family/type, exact width/depth type values, and symbolic clearance curves by line style. Body: {instanceId,widthParameterName?,depthParameterName?,lineStyleName?}.", "read back HRU403 family size and clearance"),
            new OperatorToolInfo("Query", "POST", "/revit/query", "Query", OperatorActionRisk.Low, "Read-only element query.", "query doors on Level 1"),
            new OperatorToolInfo("Query", "POST", "/revit/resolve", "Resolve", OperatorActionRisk.Low, "Read-only resolve helpers.", "resolve view \"Level 1\""),
            new OperatorToolInfo("Query", "POST", "/revit/get-element-summary", "Element Summary", OperatorActionRisk.Low, "Read-only element summaries.", "summarize selected elements"),
            new OperatorToolInfo("Query", "POST", "/revit/get-parameters", "Get Parameters", OperatorActionRisk.Low, "Read-only parameter reads. Accepts elementId, elementIds array, or single elementIds shorthand.", "get parameters for selected elements"),
            new OperatorToolInfo("Query", "POST", "/revit/measure-gap", "Measure Gap", OperatorActionRisk.Low, "Measure signed distance between two faces along a view axis. Body: {sourceElementId,source:{kind:\"face\",side},targetElementId,target:{kind:\"face\",side},axis:\"viewX\"|\"viewY\",viewId?,options?}.", "measure gap between wall left face and column right face"),
            new OperatorToolInfo("Query", "POST", "/revit/quantify", "Quantify", OperatorActionRisk.Low, "Count/list elements in category (supports grouping).", "count doors"),
            new OperatorToolInfo("Query", "POST", "/revit/quantify-visualize", "Quantify Visualize", OperatorActionRisk.Medium, "Visualize a prior /revit/quantify resultSetId. Body: {resultSetId, mode:\"highlight\"|\"isolate\"|\"new_view\"|\"clear\"|\"forget\", viewId?}.", "highlight last quantify results"),
            new OperatorToolInfo("Query", "POST", "/revit/sheets", "List Sheets", OperatorActionRisk.Low, "List sheets (action:list), count sheets (action:count / countOnly:true), or return one-sheet detail (action:detail). Detail can include placed views, viewport geometry/type metadata, sheet outline, and titleblocks for sheet-layout QC. Supports filtering by sheetNumberPrefix/query and paging via offset/limit or all:true (capped).", "print sheet A2.00"),
            new OperatorToolInfo("Query", "POST", "/revit/schedules", "Schedules", OperatorActionRisk.Low, "List schedules (action:list) or inspect one schedule (action:detail) with optional field metadata.", "list schedules"),
            new OperatorToolInfo("Query", "POST", "/revit/export-schedule-csv", "Export Schedule CSV", OperatorActionRisk.Low, "Export a schedule to CSV under Workspace artifacts. Body: {scheduleId?|query?,exact?,outputFolder?,fileName?,delimiter?,textQualifier?,columnHeaders?,dryRun?}.", "export door schedule to csv"),
            new OperatorToolInfo("Query", "POST", "/revit/export-warnings-report", "Export Warnings Report", OperatorActionRisk.Low, "List or export warnings under Workspace. Body: {action?:\"list\"|\"export\",format?:\"txt\"|\"csv\"|\"json\",offset?,limit?|max?,outputFolder?|fileName?|filePath?,includeElements?,dryRun?}.", "export warnings report as json"),
            new OperatorToolInfo("Query", "POST", "/revit/warnings", "Warnings", OperatorActionRisk.Low, "List or export warnings using a concise action contract. Body: {action?:\"list\"|\"export\",format?:\"txt\"|\"csv\"|\"json\",offset?,limit?|max?,outputFolder?|fileName?|filePath?,includeElements?,dryRun?}.", "list warnings"),
            new OperatorToolInfo("Query", "POST", "/revit/model-health", "Model Health", OperatorActionRisk.Low, "Aggregate model health stats (warnings, links, view/sheet counts, empty sheets, and unplaced views). Optional requiredSheetParameter reports sheets missing values.", "run model health"),
            new OperatorToolInfo("Query", "POST", "/revit/qa-checks", "QA Checks", OperatorActionRisk.Low, "Dedicated one-call QA checks. Body: {action:\"interference_basic\"|\"view_bounds\", ...}. `interference_basic` runs duct-vs-structural clash checks (category overrides allowed). `view_bounds` reports elements outside crop/section/scope boundaries for target views.", "run qa checks interference_basic"),
            new OperatorToolInfo("Query", "POST", "/revit/print-sets", "Print Sets", OperatorActionRisk.Low, "List print sets (action:list) or inspect one print set (action:detail,name). Optional includeSheets returns sheet members.", "list print sets"),
            new OperatorToolInfo("Query", "POST", "/revit/revisions", "Revisions", OperatorActionRisk.Low, "List project revisions with sequence/number/date/description fields when available.", "list revisions"),
            new OperatorToolInfo("Query", "POST", "/revit/get-titleblock-info", "Get Titleblock Info", OperatorActionRisk.Low, "Resolve a sheet to its titleblock instance/type/family info. Body: {sheetNumber?|sheetId?|sheetViewId?}.", "get titleblock info for sheet M000"),
            new OperatorToolInfo("Query", "POST", "/revit/titleblock-label-map", "Titleblock Label Map", OperatorActionRisk.Low, "Best-effort map of visible titleblock caption text (e.g., \"Date\") to the nearest parameter-driven label in the titleblock family. Body: {sheetNumber?|sheetViewId?|titleBlockElementId?, includeParameters?, includeHeuristics?}.", "map titleblock labels on sheet A2.00"),
            new OperatorToolInfo("Query", "POST", "/revit/capture-sheet-region", "Capture Sheet Region", OperatorActionRisk.Low, "Capture a deterministic image of a sheet region (currently: titleblock). Body: {sheetNumber?|sheetViewId?, region:\"titleblock\"?, marginFt?, imageMaxSizePx?, includeMapping?, fileName?, includeOcr?, ocrKind?, ocrExpected?, ocrTimeoutMs?}.", "capture titleblock region on sheet A2.00"),
            new OperatorToolInfo("Query", "POST", "/revit/verify-parameter-on-sheet", "Verify Parameter On Sheet", OperatorActionRisk.Low, "Read likely parameter values driving a titleblock label and (optionally) capture the titleblock region for visual verification. Body: {sheetNumber?|sheetViewId?, parameterName?|labelText?, includeCapture?, imageMaxSizePx?, marginFt?}.", "verify Date on sheet A2.00"),
            new OperatorToolInfo("Query", "POST", "/revit/titleblock-date-candidates", "Titleblock Date Candidates", OperatorActionRisk.Low, "List likely titleblock-related date parameters across titleblock instance/type, sheet, and project info. Body: {sheetNumber?|sheetViewId?|titleBlockElementId?, keywords?, includeReadOnly?, maxCandidates?}.", "list titleblock date candidates on sheet A2.00"),
            new OperatorToolInfo("Modeling", "POST", "/revit/titleblock-set-date-smart", "Titleblock Set Date (Smart)", OperatorActionRisk.High, "Apply a date value and verify the displayed titleblock date using OCR of a post-change sheet capture. Will try multiple candidate parameters and revert mismatches. Body: {sheetNumber?|sheetViewId?, labelText?, intendedValue, dryRun?|apply?, confirm?, maxCandidates?, includeOcrText?}. Requires typed confirmation when applying.", "smart set Date on sheet A2.00 to 2/10/2026"),
            new OperatorToolInfo("Modeling", "POST", "/revit/titleblock-family-update-text", "Titleblock Family Update Text", OperatorActionRisk.High, "Dev-grade family editing: update static TextNotes in a titleblock family, reload into the project (overwrite), and refresh. Body: {sheetNumber?|sheetViewId?|titleBlockElementId?|titleBlockTypeId?|familyName?, findText, replaceText, matchMode:\"exact\"|\"contains\", dryRun?|apply?, confirm?, maxEdits?}. Requires typed confirmation when applying.", "dry-run update titleblock static text on sheet A2.00"),
            new OperatorToolInfo("Query", "POST", "/revit/get-family-file-path", "Get Family File Path", OperatorActionRisk.Low, "Best-effort: return a family file path if it can be determined. Body: {familyId}. Returns pathKnown + filePath or a reason.", "get family file path for family id 12345"),
            new OperatorToolInfo("Modeling", "POST", "/revit/open-family-doc", "Open Family Doc", OperatorActionRisk.High, "Open a family document for editing. Prefer {titleblockInstanceId} for titleblocks in the active model. Body: {filePath? | familyId? | titleblockInstanceId? | elementId?}. Returns docId (session handle).", "open family doc for titleblock instance 1420968"),
            new OperatorToolInfo("Query", "POST", "/revit/find-text-notes", "Find Text Notes", OperatorActionRisk.Low, "Find TextNotes by phrase or regex in the active project document, or in an open family doc session when docId/familyDocumentId is supplied. Body: {docId?|familyDocumentId?,textContains?|contains?|regex?,viewId?,max?}. Returns TextNote ids plus owner-view context when available.", "find text notes containing \"MEP\""),
            new OperatorToolInfo("Modeling", "POST", "/revit/replace-text-note", "Replace Text Note", OperatorActionRisk.High, "Replace a TextNote’s text in the active project or an open family doc session. Body: {elementId, newText, docId?|familyDocumentId?, dryRun?|apply?, confirm?}. Requires typed confirmation when applying.", "replace text note to \"ACME\""),
            new OperatorToolInfo("Modeling", "POST", "/revit/save-family-doc", "Save Family Doc", OperatorActionRisk.High, "Save a tracked family document. With filePath, performs Save As to a guarded .rfa path under the Revit Operator workspace; otherwise saves only when the family document already has a known path. Body: {docId, filePath?, overwrite:true}.", "save this family as artifacts/families/Project Standard Tee.rfa"),
            new OperatorToolInfo("Modeling", "POST", "/revit/load-family-doc", "Load Family Doc", OperatorActionRisk.High, "Load/reload the currently-open family doc into the active project (overwrite). Body: {docId, overwriteParameterValuesOnLoad?}.", "load family doc into project"),
            new OperatorToolInfo("Modeling", "POST", "/revit/close-doc", "Close Doc", OperatorActionRisk.High, "Close an open family doc session. Body: {docId, saveChanges?}.", "close family doc"),
