            new OperatorToolInfo("Query", "POST", "/revit/find-family-text-notes", "Find Family Text Notes", OperatorActionRisk.Low, "Enumerate TextNotes in an open family edit session. Body: {familyDocumentId, contains?, max?}. Returns TextNote ids, text, and approximate location.", "find text notes containing \"MEP\""),
            new OperatorToolInfo("Modeling", "POST", "/revit/set-text-note-text", "Set Text Note Text", OperatorActionRisk.High, "Edit a TextNote's static text in the active project or an open family edit session. Body: {textNoteId, newText, familyDocumentId?, dryRun?|apply?, confirm?}. Requires typed confirmation when applying.", "set text note text to \"ACME\""),
            new OperatorToolInfo("Modeling", "POST", "/revit/reload-family-edit-session", "Reload Family (Edit Session)", OperatorActionRisk.High, "Reload an edited family document back into the project (overwrite) and optionally close the session. Body: {familyDocumentId, overwriteParameterValues?, closeSession?}.", "reload edited titleblock family"),

