            new OperatorToolInfo("Capture", "POST", "/revit/capture-screenshare", "Capture Screenshare", OperatorActionRisk.Low, "Capture the Revit window (screenshare) and attach image + context for visual grounding. Body: {includeContext?:bool}.", "capture screenshare"),
            new OperatorToolInfo("Capture", "POST", "/revit/export-pdf", "Export PDF", OperatorActionRisk.Low, "Export view(s)/sheet(s) to PDF. Provide viewIds OR selector OR sheetNumberPrefix/sheetQuery/sheetGroup OR printSetName; dryRun/preflight returns exact selected sheets and output paths before export. Use combine:false plus perSheetFileNameTemplate for individual PDFs with custom names. Use colorMode BlackLine for black-and-white, Grayscale for grayscale, or Color for color.", "preflight export all power sheets to one pdf"),
