            new OperatorToolInfo("Capture", "POST", "/revit/export-images", "Export Images (Batch)", OperatorActionRisk.Low, "Batch export images for selected views/sheets (supports selector + dry-run). Body: {viewIds?|selector?,imageSize?,outputFolder?,fileNameTemplate?,dryRun?}.", "export images for sheets starting with A"),
            new OperatorToolInfo("Capture", "POST", "/revit/export-dwg", "Export DWG", OperatorActionRisk.Low, "Batch export DWG for selected views/sheets (supports selector + dry-run). Body: {viewIds?|selector?,outputFolder?,baseFileName?,dryRun?}.", "export dwg for sheets starting with A"),
            new OperatorToolInfo("Capture", "POST", "/revit/export-ifc", "Export IFC", OperatorActionRisk.Low, "Export IFC to Workspace artifacts (supports optional view filter + dry-run). Body: {fileName?,outputFolder?,viewId?,dryRun?}.", "export ifc"),
            new OperatorToolInfo("Selection", "POST", "/revit/export-view-frame", "Export View Frame", OperatorActionRisk.Low, "Export view image + optional raster-consistent mapping metadata.", "export view frame and include mapping"),
            new OperatorToolInfo("Selection", "POST", "/revit/export-view-region", "Export View Region", OperatorActionRisk.Low, "Export a deterministic image + raster-consistent mapping for a specified region of a view. Set preserveViewSpecificDetailing:true when the evidence includes DetailCurves, text, or other view-specific annotations; it is opt-in because detailed production plans can be large. Body: {viewId?,imageMaxSizePx?,includeMapping?,preserveViewSpecificDetailing?,fileName?,region:{mode:\"focusElements\",focusElementIds:[...],marginFt?}|{mode:\"center\",centerX,centerY,halfWidth,halfHeight}}. Should not leave persistent changes to the user's view.", "export a region around element ids 123,456"),
            new OperatorToolInfo("Selection", "POST", "/revit/export-visible-elements", "Export Visible Elements", OperatorActionRisk.Low, "Export a mapped view image plus visible-element inventory on the same raster-consistent coordinate basis. Returns element ids, category/type/source/host context, explicit hostingSurface + link-host metadata, orientation payloads (facing/hand/basis/rotation), bbox/location geometry, image-space coordinates, visibleText for TextNotes/tags, and taggedSpatial for room/space tags in supported 2D views. Linked annotation tags use their transformed tag-head positions for frame inclusion, mapping, and geometry when a model bounding box is unavailable. Optional modelBounds:[minX,minY,minZ,maxX,maxY,maxZ] restricts host and transformed linked elements to an intersecting host-model box before the safety limit is applied. Body: {viewId?,imageSize?,includeMapping?,categories?,excludeCategories?,includeGeometry?,includeLinked?,modelBounds?,limit?}.", "export visible electrical devices with mapping"),
            new OperatorToolInfo("Selection", "POST", "/revit/pick-at-pixel", "Pick At Pixel", OperatorActionRisk.Low, "Resolve elements near a pixel in a frame. Supports category-aware filtering: {includeCategories?,excludeCategories?,prefer:\"modelGeometry\"|\"annotation\"|\"any\",maxHits?}. Returns ranked hits with distances.", "pick wall at pixel 1200,800 with includeCategories:[\"OST_Walls\"]"),
            new OperatorToolInfo("Selection", "POST", "/revit/highlight-and-export", "Highlight And Export", OperatorActionRisk.Low, "Highlight element IDs and export an image. Supports highlightGroups (per-group colors), labels (temporary text notes), and returns elementVisibility diagnostics proving whether each requested element is visible in the requested view.", "highlight source/target and export image"),
            new OperatorToolInfo("Selection", "POST", "/revit/activate-view", "Activate View", OperatorActionRisk.Low, "Switch active view.", "activate view \"Level 1\""),
            new OperatorToolInfo("Selection", "POST", "/revit/set-selection", "Set Selection", OperatorActionRisk.Low, "Set the current selection to specific element IDs.", "select element id 123"),
            new OperatorToolInfo("Selection", "POST", "/revit/resolve-room-plan-view", "Resolve Room Plan View", OperatorActionRisk.Low, "Resolve the best plan view for a room or space number and return candidate ranking.", "resolve a room plan view for Level 1"),
            new OperatorToolInfo("Electrical", "POST", "/revit/plan-dwelling-receptacles", "Plan Dwelling Receptacles", OperatorActionRisk.Low, "Read-only deterministic perimeter receptacle proposal for one room/space using the bounded DWELLING-RECEPTACLES-V1 office profile. Returns grounded wall hosts, opening exclusions, existing-device coverage, proposed placements, assumptions, and manual-review blockers. It does not create devices, circuits, or claim code compliance.", "plan office-standard receptacles in Room 403"),
            new OperatorToolInfo("Electrical", "POST", "/revit/plan-room-receptacles-from-analog", "Plan Room Receptacles From Analog", OperatorActionRisk.Low, "Rollback-only native plan and visual preview that discovers a unique same-level furnished analog room, maps its exact receptacle type inventory to corresponding semantic anchors and linked boundary faces, and returns an approval-bound plan hash. circuitMode=match_source_system additionally proves each source has exactly one panel-assigned power system, temporarily joins each proposed device through the real ElectricalSystem, and returns exact system-ID plus factual panel/circuit/load readback before rollback. Default circuitMode=none creates no circuit membership.", "plan Room 403 receptacles and match the exact source circuits from Room 405"),
            new OperatorToolInfo("Electrical", "POST", "/revit/apply-room-receptacles-from-analog", "Apply Room Receptacles From Analog", OperatorActionRisk.High, "High-risk atomic apply of a previously hashed native analog receptacle plan. Recomputes the plan, places exact face-hosted family types, verifies room/type/host/position/orientation readback, and refuses stale or nonempty targets. When the approved plan used circuitMode=match_source_system, the apply atomically joins and verifies the exact source ElectricalSystem IDs and reports factual before/after loads without making capacity or code-compliance claims.", "apply the approved Room 403 analog receptacle and source-circuit plan"),
            new OperatorToolInfo("Types", "POST", "/revit/list-element-types", "List Element Types", OperatorActionRisk.Low, "Type list + family-type maintenance helper. Actions: list (default), rename_types, purge_unused_in_family. List supports {category|categories, exactName?, nameContains?, familyNameContains?, includeParameters?, limit?, exportCsv?, outputFolder?, fileName?}. Rename supports {action:\"rename_types\",familyName,searchPattern,replaceWith?,regexIgnoreCase?,maxEdits?,category|categories?,dryRun?}. Purge supports {action:\"purge_unused_in_family\",familyName,maxDelete?,category|categories?,dryRun?}.", "dry-run rename family types by regex"),
            new OperatorToolInfo("Types", "POST", "/revit/resolve-element-type", "Resolve Element Type", OperatorActionRisk.Low, "Resolve an ElementType by name without listing everything. Request: {category, typeName, familyName?, exact?, includeParameters?, cacheBust?}.", "resolve wall type \"Generic - 4\\\"\""),

            new OperatorToolInfo("Safety", "POST", "/revit/transaction-plan", "Plan Transaction", OperatorActionRisk.Medium, "Dry-run a list of transaction actions and return impact summary without applying. Body: {actions:[...]}.", "plan a set of changes (dry run)"),
            new OperatorToolInfo("Safety", "POST", "/revit/transaction-validate", "Validate Plan", OperatorActionRisk.Medium, "Validate post-conditions after a transaction using checks. Body: {transactionId?,checks?}.", "validate expected model state"),
            new OperatorToolInfo("Safety", "POST", "/revit/transaction-apply", "Apply Plan", OperatorActionRisk.High, "Apply transaction actions and emit transaction-scoped model diff (session + step scopes) with optional persisted JSON artifact. Body: {actions:[...],diff?}.", "apply actions and return transaction diff"),

            new OperatorToolInfo("Drafting", "POST", "/revit/visibility", "View Visibility", OperatorActionRisk.Medium, "Read/update view settings. Actions: get, set_template, hide_category, show_category, set_scale, set_detail_level, set_discipline, set_phase, set_phase_filter, set_section_box, clear_section_box, set_crop_box, clear_crop_box, set_underlay, clear_underlay, set_category_override, clear_category_override, apply_view_filter, create_view_filter, remove_view_filter, clear_filter_override, isolate_elements_temp, isolate_categories_temp, clear_temp_hide_isolate, reveal_hidden_on, reveal_hidden_off, hide_elements, unhide_elements. get with includeLinkedModels:true reports loaded Revit links, common linked categories, linked phases, and phase-map rows when available. Linked-model category override requests block with linked_model_category_override_not_supported rather than changing host categories. set_crop_box supports annotationCropActive and annotationCropMarginFeet for tight sheet viewport extents. Supports linePatternId|linePatternName in category/filter overrides, and create_view_filter rule fields {ruleParameterName,ruleOperator,ruleValue,ruleCaseSensitive}.", "create and apply a view filter for supply ducts"),
            new OperatorToolInfo("Drafting", "POST", "/revit/datums", "Datum Tools", OperatorActionRisk.Medium, "List/create/update grid/level datum settings. Actions: list|get, create_grid, create_level, set_scope_box, clear_scope_box, set_bubble_visibility. Body: {action?,viewId?,datumType?:\"grid\"|\"level\"|\"all\",datumIds?,nameContains?,max?,scopeBoxId?|scopeBoxName?,bubbleVisible?,bubbleEnd?:\"start\"|\"end\"|\"both\",p1?,p2?,elevation?,name?,dryRun?}.", "set scope box for matching grids"),
            new OperatorToolInfo("Drafting", "POST", "/revit/create-text", "Create Text Note", OperatorActionRisk.Medium, "Create text notes, list text note types, or create a text note type/style. Actions: create|list_types|create_type. Body: {action?,viewId?,x?,y?,text?,typeId?|typeName?,newTypeName?,baseTypeId?|baseTypeName?,fontName?,textSize?,bold?,italic?,allowExisting?,dryRun?}.", "create a new text type and place a note"),
            new OperatorToolInfo("Drafting", "POST", "/revit/import-drawing-spec", "Import Drawing Spec", OperatorActionRisk.Medium, "Import a .docx or .txt from Workspace into a drafting view as multi-column TextNotes. Body: {sourcePath,viewId?,viewName?,textTypeName?,columns?,columnWidthInches?,columnHeightInches?,gutterInches?,marginInches?,startXInches?,startYInches?,dryRun?}", "import drawing spec from artifacts/specs/Project_Spec.docx"),
            new OperatorToolInfo("Drafting", "POST", "/revit/import-excel-table", "Import Excel Table", OperatorActionRisk.Medium, "Import an .xlsx range into a drafting view as a grid of detail lines + text notes. Body: {sourcePath,sheetName?,range,viewId?,viewName?,textTypeName?,lineStyleName?,cellWidthInches?,cellHeightInches?,marginInches?,startXInches?,startYInches?,sheetNumber?,sheetViewId?,dryRun?}", "import excel table from artifacts/uploads/vent.xlsx range A1:G40"),
            new OperatorToolInfo("Drafting", "POST", "/revit/export-elements-xlsx", "Export Elements → .xlsx", OperatorActionRisk.Low, "Export selected elements + parameter columns to an .xlsx under Workspace. Body: {elementIds:[...],parameterNames:[...],outputFolder?,fileName?,dryRun?}.", "export selected elements to xlsx"),
            new OperatorToolInfo("Drafting", "POST", "/revit/import-elements-xlsx-updates", "Import .xlsx → Parameter Updates", OperatorActionRisk.High, "Import parameter updates from an .xlsx range (header row required) using UniqueId or ElementId keys. Supports dry-run diff. Body: {sourcePath,sheetName?,range,idColumn?,behavior?,dryRun?}.", "dry-run import parameter updates from xlsx"),
            new OperatorToolInfo("Drafting", "POST", "/revit/create-drafting-view", "Create Drafting View", OperatorActionRisk.Medium, "Create (or reuse) a Drafting View by name. Body: {name,scale?,allowExisting?}", "create drafting view \"Typical Detail\""),
            new OperatorToolInfo("Modeling", "POST", "/revit/create-view", "Create View", OperatorActionRisk.High, "Create floor-plan, 3D, dependent, callout, section, elevation, camera, drafting, legend (from existing legend duplication), and view-template views; also supports batch view rename. Body: {action:\"create_floor_plan\"|\"create_3d\"|\"create_dependent\"|\"create_callout\"|\"create_section\"|\"create_elevation\"|\"create_camera\"|\"create_drafting\"|\"create_legend\"|\"create_view_template\"|\"rename_batch\",name?,levelId?|levelName?,planType?,perspective?,sourceViewId?,calloutType?,sectionHeight?,sectionDepth?,elevationIndex?,p1?,p2?,eye?,target?,up?,templateId?|templateName?,scale?,detailLevel?,discipline?,viewIds?,nameContains?,prefix?,suffix?,findText?,replaceText?,exact?,max?,dryRun?}.", "create a floor plan for Level 2"),
            new OperatorToolInfo("Drafting", "POST", "/revit/draw-detail-curves", "Draw Detail Curves", OperatorActionRisk.Medium, "Draw detail curves in a view. Supports point.xyz (feet), point.xPx/yPx (requires frameId), and point.xIn/yIn (inches). Optional expectedViewType and expectedLevelName fail closed if the target plan does not match; projectToViewPlane projects resolved points onto the target view plane. Optional `lineStyleCreate` creates/updates a line style before drawing. Body: {viewId,frameId?,expectedViewType?,expectedLevelName?,projectToViewPlane?,lineStyleName?,lineStyleCreate?,curves:[{kind:\"line\",a,b}|{kind:\"polyline\",points:[...] }|{kind:\"arc\",a,b,c}],dryRun?}", "create a line style and draw detail lines"),
            new OperatorToolInfo("Drafting", "POST", "/revit/annotation-symbol-leaders", "Annotation Symbol Leaders", OperatorActionRisk.Medium, "Read or replace the native leaders attached to one Generic Annotation symbol. Read is non-mutating. Replace supports dry-run rollback and exact end/elbow coordinates in model feet. Body: {action:\"read\"|\"replace\",elementId,leaders?:[{endXyz:[x,y,z],elbowXyz?:[x,y,z]}],dryRun?}.", "read a generic annotation leader, then replace it with exact source-supported geometry"),
            new OperatorToolInfo("Drafting", "POST", "/revit/create-filled-region", "Create Filled Region", OperatorActionRisk.Medium, "Create filled regions, list filled region types, or create a filled region type. Actions: create|list_types|create_type. Body: {action?,viewId?,frameId?,typeId?|typeName?,newTypeName?,sourceTypeId?|sourceTypeName?,fillPatternName?,allowExisting?,loops?,dryRun?}", "create a filled region type with hatch and apply it"),
            new OperatorToolInfo("Drafting", "POST", "/revit/create-revision-cloud", "Create Revision Cloud", OperatorActionRisk.Medium, "Create a revision cloud in a view, with optional one-call tagging of the created cloud. Body: {viewId,frameId?,points:[...],revisionId?,closed?,tagCreatedCloud?,tagHasLeader?,dryRun?}", "create a revision cloud around this outline"),
            new OperatorToolInfo("Drafting", "POST", "/revit/keynotes", "Keynote Tools", OperatorActionRisk.Medium, "Query and update keynote data. Actions: list_tags, list_elements_missing_keynote, set_element_keynote. Body: {action?,viewId?,elementIds?,categoryNames?,keynoteValue?,max?,dryRun?}.", "list keynote tags in a view"),
            new OperatorToolInfo("Drafting", "POST", "/revit/tag-elements", "Tag Elements", OperatorActionRisk.Medium, "Create tags for elements by explicit ids and/or category selectors in a target view, with duplicate avoidance, optional per-category tag-type mapping, and additive geometry-aware placement/readback. geometry_aware places tag heads outside target footprints, avoids annotation/target/tag collisions, prefers clear plan space over walls and modeled equipment, keeps leaders bounded, rejects leader crossings and protected-content routes, uses discipline profiles, and requires actual Revit tag and leader geometry before retaining created work. Existing tags can be read or repaired in place with repairExistingTagId plus exact tag-head/free-leader coordinates; dry runs execute the native tag repair, read it back, roll it back, and verify the original tag geometry. If no compatible tag is loaded, autoLoadTagFamily can import an exactly category-compatible tag from a workspace-scoped source project, optionally selecting an exact source family/type; dry-run reports bounded source candidates. generatedTagContentProfile=airflow_only produces a copied source family that retains bounded flow-unit labels and removes unrelated text/label content, with an explicit sanitization receipt. A dry-run may set inspectTagFamilyElements=true to return a bounded read-only inventory of the selected tag family's internal elements and parameters. Tags with no visible/measurable head geometry or no professionally clear tag/leader route are removed and reported as failures. Create body: {viewId?|viewName?,elementIds?|categoryNames?,categoryTagTypeMap?,tagTypeId?|tagTypeName?|tagFamilyName?,onlyUntagged?,addLeader?,orientation?:horizontal|vertical,offsetX?,offsetY?,placementMode?:offset|geometry_aware,placementProfile?:auto|mep|electrical|architectural,tagWidthPaperInches?,tagHeightPaperInches?,clearancePaperInches?,maxRepairAttempts?,autoLoadTagFamily?,tagFamilySourceProjectPath?,tagFamilySourceCategory?,tagFamilySourceFamilyName?,tagFamilySourceTypeName?,generatedTagFamilyName?,generatedTagContentProfile?:none|airflow_only,inspectTagFamilyElements?,max?,dryRun?}. Existing-tag body: {viewId?|viewName?,repairExistingTagId,tagHeadPositionXyz?,leaderEndXyz?,leaderElbowXyz?,hasLeader?,leaderEndCondition?:attached|free,dryRun?}.", "repair an existing tag head and free leader endpoint with rollback verification"),
            new OperatorToolInfo("Drafting", "POST", "/revit/create-dimension", "Create Dimension", OperatorActionRisk.Medium, "Create dimensions (annotations).", "dimension between these walls"),

            new OperatorToolInfo("Modeling", "POST", "/revit/create-sheet", "Create Sheet", OperatorActionRisk.High, "Create a real or placeholder sheet, or convert a placeholder to real. Auto titleblock now defaults to the most-used/adjacent non-one-off titleblock, not collector-first. Body: {name?,number?,titleBlockId?(-1=auto),titleBlockName?,referenceSheetNumber?,placeholder?,convertPlaceholderSheetId?}.", "create sheet E400 enlarged electrical plans"),
            new OperatorToolInfo("Modeling", "POST", "/revit/create-sheets", "Create Sheets (Batch)", OperatorActionRisk.High, "Batch create sheets with placeholder lifecycle support. Auto titleblock defaults to most-used/adjacent titleblock unless overridden. Body: {sheets?:[{name?,number?,titleBlockId?,titleBlockName?,referenceSheetNumber?,placeholder?,convertPlaceholderSheetId?}],sourceCsvPath?,csvDelimiter?,titleBlockIdDefault?,titleBlockNameDefault?,referenceSheetNumberDefault?,behavior?,dryRun?}. CSV headers support sheetNumber|number and sheetName|name.", "create sheets from artifacts/uploads/sheets.csv"),
            new OperatorToolInfo("Modeling", "POST", "/revit/create-print-set", "Create Print Set", OperatorActionRisk.High, "Create (or overwrite) a named print set from selected sheets. Body: {name,sheetIds?|sheetNumbers?|query?|all?,exact?,max?,overwrite?,dryRun?}.", "create print set ISSUE-SET from sheets A1*"),
            new OperatorToolInfo("Modeling", "POST", "/revit/create-revision", "Create Revision", OperatorActionRisk.High, "Create a revision and optionally set date/description/issued fields. Body: {description?,revisionDate?,issued?,issuedBy?,issuedTo?,dryRun?}.", "create revision IFC ISSUE"),
            new OperatorToolInfo("Modeling", "POST", "/revit/apply-revision-to-sheets", "Apply Revision To Sheets", OperatorActionRisk.High, "Add or replace additional revisions on selected sheets. Body: {revisionId,sheetIds?|sheetNumbers?|query?|all?,mode:\"append\"|\"replace\",dryRun?}.", "apply revision 123 to sheets A1*"),
            new OperatorToolInfo("Modeling", "POST", "/revit/place-view", "Place View On Sheet", OperatorActionRisk.High, "Place or move a view on a sheet. Supports selectors (`sheetId|sheetNumber|sheetQuery`, `viewId|viewName|viewQuery`), viewport, regular schedule, and panel schedule placement. For moving schedules between sheets, use moveIfAlreadyPlaced:true; omitted x/y defaults to avoidOverlap:true and chooses a free sheet position. Body: {sheetId?|sheetNumber?|sheetQuery?,sheetExact?,viewId?|viewName?|viewQuery?,viewExact?,x?,y?,moveIfAlreadyPlaced?,avoidOverlap?,lockViewport?,viewportTypeId?|viewportTypeName?,dryRun?}.", "move panel schedule EL1 to E302 without overlapping existing schedules"),
            new OperatorToolInfo("Modeling", "POST", "/revit/place-views", "Place Views (Batch)", OperatorActionRisk.High, "Batch place or move views onto sheets. Supports viewport, regular schedule, and panel schedule placements, selector-based sheet/view resolution, optional move-if-already-placed, schedule avoidOverlap, viewport lock, and viewport type assignment per item. Body: {placements:[{sheetId?|sheetNumber?|sheetQuery?,sheetExact?,viewId?|viewName?|viewQuery?,viewExact?,x?,y?,moveIfAlreadyPlaced?,avoidOverlap?,lockViewport?,viewportTypeId?|viewportTypeName?}],behavior?,dryRun?}.", "batch move schedules onto sheets using avoidOverlap"),
            new OperatorToolInfo("Modeling", "POST", "/revit/align-viewports", "Align Viewports", OperatorActionRisk.High, "Align primary viewports by sheet number/id or explicit viewport ids. For sheet flipping/building-location tasks use sheetNumbers + referenceSheetNumber + primaryOnly:true + viewNameContains:\"POWER PLAN\"; omitted mode defaults to model-coordinate alignment using the reference view crop-center so different viewport/crop sizes still align building content. Boundary checking is on by default: proposed viewport outlines are checked against the titleblock/sheet usable area with options.boundaryPolicy skip|warn|fail|allow (default skip) and options.boundaryMarginInches. Use mode:\"box\" only when intentionally aligning viewport boxes; use modelAnchorElementId for a specific shared stair/core anchor. Body: {referenceSheetId?|referenceSheetNumber?|referenceSheetQuery?,referenceViewportId?,sheetIds?|sheetNumbers?|sheetNumberPrefix?|sheetQuery?|viewportIds?,primaryOnly?,viewNameContains?,mode?,anchorStrategy?,alignTo?,horizontal?,vertical?,offsetX?,offsetY?,modelAnchor?,modelAnchorElementId?,dryRun?,options?}.", "align E100-E106 power plan building location to E102"),
            new OperatorToolInfo("Modeling", "POST", "/revit/renumber-sheets", "Renumber Sheets", OperatorActionRisk.High, "Renumber/rename sheets by explicit mapping (supports dry-run). Body: {changes:[{sheetId,newNumber?,newName?}],behavior?,dryRun?}.", "renumber sheets"),
            new OperatorToolInfo("Modeling", "POST", "/revit/sync-sheet-names", "Sync Sheet Names", OperatorActionRisk.High, "Set sheet names to the primary viewport view name (supports dry-run). Body: {sheetIds:[...],force?,dryRun?}.", "sync sheet names to primary view name"),
            new OperatorToolInfo("Modeling", "POST", "/revit/link-cad", "Link CAD (DWG) Into View/Sheet", OperatorActionRisk.High, "Link (or import) a DWG into a target view and optionally place that view on a sheet. Sheet-only requests default to create/reuse a Drafting View at viewScale:1 and place it as a viewport; set directSheetImport:true only for legacy sheet-owned CAD imports. Body: {sourcePath,sheetNumber?,sheetViewId?,viewId?,viewName?,viewQuery?,createDraftingView?,placeOnSheet?,moveIfAlreadyPlaced?,directSheetImport?,viewScale?,placement:\"origin\"|\"center\"?,x?,y?,xInches?,yInches?,importUnit?,customScale?,link?,preflightOnly?,dryRun?}. Use dryRun:true with preflightOnly:true for a no-source-required capability probe. Use customScale:1 for explicit one-to-one scale when supported; result returns ownerViewId, viewportId, bounding boxes, and cadCategories for layer/subcategory graphics overrides.", "link cad P:\\\\Projects\\\\refs\\\\keyplan.dwg into a drafting view and place it on sheet A1.00"),
            new OperatorToolInfo("Modeling", "POST", "/revit/link-revit", "Link Revit Model", OperatorActionRisk.High, "Link an RVT model into the active document at origin with optional XYZ offset and pinning, reload an existing link type from an exact RVT path while preserving its instances and placement, or unload a link type before strict cleanup. Body: {action?:\"link\",sourcePath,dryRun?,pin?,x?,y?,z?}, {action:\"reload\",linkTypeId,sourcePath,dryRun?}, or {action:\"unload\",linkTypeId,dryRun?}. sourcePath can be workspace-relative or under OPERATOR_ALLOWED_EXTERNAL_ROOTS.", "reload architectural link type 123 from refs\\\\architectural.rvt"),
            new OperatorToolInfo("Modeling", "POST", "/revit/place-image", "Place Image (Sheet or View)", OperatorActionRisk.High, "Place an image (.png/.jpg) onto a sheet OR into any view. Body: {sourcePath,viewId?,sheetNumber?,sheetViewId?,placement:\"origin\"|\"center\"?,xInches?,yInches?,widthInches?,heightInches?,dryRun?}.", "place image artifacts/uploads/redline.png into drafting view id 12345"),
            new OperatorToolInfo("Modeling", "POST", "/revit/place-pdf-underlay", "Place PDF Underlay (Drafting View)", OperatorActionRisk.High, "Import a PDF into a target view (default: create/reuse a drafting view), optionally place that view onto a sheet. Body: {sourcePath,viewId?,viewName?,sheetNumber?,sheetViewId?,pageNumber?,placement:\"origin\"|\"center\"?,xInches?,yInches?,dryRun?}.", "place pdf underlay artifacts/uploads/keyplan.pdf onto sheet A1.00"),
            new OperatorToolInfo("Modeling", "POST", "/revit/import-zippybim-geometry", "Import Floor Plan Geometry", OperatorActionRisk.High, "Atomically create walls and optional hosted doors/windows from registered geometry in feet. Legacy prediction imports may normalize wall geometry and choose nearby types/hosts; strict reconstruction can preserve diagonal walls and fail closed on exact wall/opening types, source wall hosts, level elevation, count limits, or skipped elements. Body: {geometry:{metadata?,elements:[{id?,element:\"wall\",path:[[x1,y1],[x2,y2]],thickness?,height?,typeName?}|{id?,element:\"door\"|\"window\",position:[x,y],width?,height?,familyName?,typeName?,hostWallId?,chainageFt?,sillHeight?}]},sourcePath?,levelId?|levelName?,levelElevationFt?,defaultWallHeightFeet?,minWallLengthFeet?,disableWallJoins?,importDoors?,importWindows?,normalizeWallGeometry?,requireExactWallTypes?,requireExactOpeningTypes?,requireSourceWallHosts?,requireAllElements?,maximumCreatedElements?,maximumOpeningHostDistanceFeet?,dryRun?}.", "reconstruct registered walls doors and windows from a floor plan with exact source-host grounding"),
            new OperatorToolInfo("Modeling", "POST", "/revit/create-schedule", "Create Schedule", OperatorActionRisk.High, "Create schedule views with kind + placement helpers. Body: {name|scheduleName,category|categoryName?,kind?:regular|material_takeoff|key|keynote_legend|multi_category|sheet_list|view_list|clone,sourceScheduleId?|sourceQuery?|sourceExact?,fields?|addFields?,includeLinkedFiles?,filterBySheet?,reuseIfExists?,placeOnSheet?,placeOnActiveSheet?,placeOnActiveSheetX?,placeOnActiveSheetY?,dryRun?}.", "create a keynote legend filtered to the active sheet"),
            new OperatorToolInfo("Modeling", "POST", "/revit/configure-schedule", "Configure Schedule", OperatorActionRisk.High, "Apply advanced schedule configuration: fields, calculated fields/formulas, filters, sort/group, conditional formatting, field styling, appearance, filter-by-sheet, column widths, and row heights. Body: {scheduleId?|query?,addFields?,calculatedFields?,filters?,sortGroup?,showGrandTotals?,columnWidths?,rowHeights?,fieldFormats?,conditionalFormats?,appearance?,filterBySheet?,replaceFilters?,replaceSortGroup?,dryRun?}.", "configure a door schedule"),
