            new OperatorToolInfo("Modeling", "POST", "/revit/create-pipe", "Create Pipe", OperatorActionRisk.High, "Create one straight pipe segment from XYZ points or frame-linked view pixels. Use dryRun first for redline/model-coordinate tasks. Body: {levelName?,startX?,startY?,startZ?,endX?,endY?,endZ?,frameId?,startPoint?,endPoint?,systemType?,pipeType?,diameter?|pipeSize?,dryRun?}.", "dry-run create a 2 inch domestic cold water pipe segment from the marked line"),
            new OperatorToolInfo("Modeling", "POST", "/revit/create-family-instance", "Create Family Instance", OperatorActionRisk.High, "Place one or more family instances. Supports symbolName or typeName alias, optional levelName, target view/sheet placement (viewId|sheetNumber), spacing arrays (count + spacingX/Y/Z), rotationDegrees, and dryRun.", "place a north-arrow symbol on sheet A1.00"),
            new OperatorToolInfo("Modeling", "POST", "/revit/place-families", "Place Families", OperatorActionRisk.High, "Batch place family instances from a spec. Supports default levelName, optional per-instance levelName override, instance parameters, exact user-workset assignment by worksetName or worksetId with native verification, and an explicit allowUnhostedWorkPlanePlacement opt-in for work-plane-based families that project standards intentionally place without a host.", "place VAVs for these rooms"),
new OperatorToolInfo("Modeling", "POST", "/revit/place-family-instance-on-host", "Place Family Instance On Host", OperatorActionRisk.High, "Place a family instance onto a specific host using an exemplar/type plus host-relative offsets, wall-chainage inputs, an exact native element face, optional room-side link-host context or an exact category-bound linked model element inside a RevitLinkInstance, orientation matching, explicit verified work-plane flip state, verified source created-phase and workset inheritance, optional electrical-circuit matching from the source exemplar, exact compatible electrical distribution-system assignment for panelboards, parameter copy, and preview export. Work-plane-based families may use an exact non-wall native host element. sourceHostFaceStableReference can rebind an exact face; when source and target stable-reference suffixes differ, hostFacePointXyz selects the source-grounded target face independently from the final pointXyz insertion location, and hostFaceNormalXyz constrains parallel or perpendicular candidate faces to the source-grounded outward normal. The created instance must retain the exact requested host. Explicit linked-wall placement clamps the requested plan point along that exact wall while preserving its lateral room-side offset for finish-face resolution, and requires a vertical face. Explicit linked non-wall placement requires linkedHostBuiltInCategory, resolves the nearest real model face of any orientation near the requested point, and verifies that the created instance retained the exact linked element host. Missing or ambiguous faces fail closed. pointXyz, hostFacePointXyz, and hostFaceNormalXyz, when provided, must each contain exactly three finite numeric coordinates. workPlaneFlipped applies and verifies the final Revit FamilyInstance work-plane flip; when omitted and an orientation source is supplied, copyFacingHandState also preserves the source work-plane flip. A missing panel distribution system can be created atomically from source-grounded exact settings via ensureDistributionSystem; dry-run rolls the new voltage/distribution definitions back with the instance. Body: {sourceElementId?|familySymbolId?|familyName+symbolName,hostElementId,linkedHostElementId?,linkedHostBuiltInCategory?,sourceHostFaceStableReference?,referenceDirectionXyz?,hostFacePointXyz?,hostFaceNormalXyz?,roomId?|roomNumber?,roomSide?,referenceElementId?,pointXyz?,alongHostOffsetFt?,targetChainageFt?,targetNormalizedChainage?,elevationFt?|elevationDeltaFt?,matchOrientationFromSource?,orientationSourceElementId?,copyRotation?,copyFacingHandState?,workPlaneFlipped?,matchElectricalCircuitFromSource?,requireElectricalCircuitMatch?,parameterNamesToCopy?,parameterOverrides?,distributionSystemName?,ensureDistributionSystem?:{name,electricalPhase,phaseConfiguration,numWires,voltageLineToLine?:{name,actualValue,minValue,maxValue},voltageLineToGround?:{name,actualValue,minValue,maxValue}},dryRun?,includePreviewImage?,previewViewId?,previewImageSize?,focusPaddingFt?}.", "dry-run place a hosted 208V panel and ensure its exact source-grounded distribution system"),
new OperatorToolInfo("Modeling", "POST", "/revit/create-similar-from-instance", "Create Similar From Instance", OperatorActionRisk.High, "Create one or more hosted copies from an exemplar instance, preserving hosting behavior, orientation, and the exemplar workset with native verification while supporting exact host slots via wall-chainage or explicit point placements plus preview. Optionally match the source exemplar's electrical circuit. Body: {exemplarElementId,hostElementId?,roomId?|roomNumber?,roomSide?,referenceElementId?,alongHostOffsetsFt?|placements?,matchOrientationFromSource?,orientationSourceElementId?,copyRotation?,copyFacingHandState?,matchElectricalCircuitFromSource?,requireElectricalCircuitMatch?,parameterNamesToCopy?,parameterOverrides?,dryRun?,includePreviewImage?,previewViewId?,previewImageSize?,focusPaddingFt?}.", "dry-run create two similar receptacles from this exemplar on the same wall and keep them on the same circuit"),
            new OperatorToolInfo("Modeling", "POST", "/revit/adjust-hosted-instance-on-host", "Adjust Hosted Instance On Host", OperatorActionRisk.High, "Move and/or reorient an existing hosted family instance along its resolved host frame using chainage, relative host offsets, or explicit target points, with optional orientation matching, electrical-circuit preservation/reassignment, deterministic placement validation, and preview export. Linked-face hosted instances are atomically recreated on the resolved face and the original is deleted only after validation; the response reports originalElementId, the current elementId, and replacementStrategy. Body: {elementId,roomId?|roomNumber?,roomSide?,orientationSourceElementId?,electricalCircuitSourceElementId?,matchOrientationFromSource?,matchElectricalCircuitFromSource?,requireElectricalCircuitMatch?,copyRotation?,copyFacingHandState?,pointXyz?,alongHostDeltaFt?,targetChainageFt?,targetNormalizedChainage?,rotateToHostRelativeDegrees?,dryRun?,includePreviewImage?,previewViewId?,previewImageSize?,focusPaddingFt?,label?}.", "adjust this created receptacle along the wall, preserve its circuit, and preview the correction"),
new OperatorToolInfo("Modeling", "POST", "/revit/assign-electrical-circuit", "Assign Electrical Circuit", OperatorActionRisk.High, "Create, assign, or repair native electrical circuit membership for family instances. sourceElementId requires exactly one retained source power system and verifies that exact system ID. createSystemType:\"PowerCircuit\" creates one new ElectricalSystem from uncircuitized elementIds. electricalSystemId moves one existing exact-member PowerCircuit into targetPanelSlotNumber without recreating or discarding its members. Both exact-slot modes fail closed when expectedCircuitNumber differs from Revit's resulting CircuitNumber, and a dryRun exercises the real panel-schedule move inside a rollback-verified TransactionGroup. panelName/circuitNumber remain non-membership labels and are attempted only when parameterOnlyFallback:true is explicitly supplied without a native membership mode. Body: {elementIds,sourceElementId?,createSystemType?:\"PowerCircuit\",electricalSystemId?,panelElementId?,targetPanelSlotNumber?,expectedCircuitNumber?,panelName?,circuitNumber?,dryRun?,confirm?,parameterOnlyFallback?}.", "dry-run creating or moving a PowerCircuit into an exact panel schedule slot with rollback verification"),
